/** Load a scenario into an object shaped like S (works for the port's S and the extracted single-file code's S). */
export function load(S: any, o: { tickets?: any[]; customers?: any[]; staff?: any[]; shifts?: any[]; queues?: any[]; pins?: any[]; names?: Record<string, string>; meId?: string | null; isEditor?: boolean; counters?: any }) {
  const clone = (x: any) => JSON.parse(JSON.stringify(x));
  S.tickets = clone(o.tickets || []); S.byId = new Map(S.tickets.map((t: any) => [t.id, t]));
  S.customers = clone(o.customers || []); S.custById = new Map(S.customers.map((c: any) => [c.id, c])); S.custByName = new Map(S.customers.map((c: any) => [String(c.name || "").toLowerCase(), c]));
  S.staff = clone(o.staff || []); S.shifts = clone(o.shifts || []); S.queues = clone(o.queues || []); S.pins = clone(o.pins || []);
  S.names = Object.assign({}, o.names || {}); S.meId = o.meId || null; S.isEditor = !!o.isEditor; S.counters = clone(o.counters || {}); S.canWrite = true;
}

/*
 * Scenario runners. Each takes an API (the module functions plus S, setCfg and
 * setDb) and returns plain data. legacy-expected.json is these same runners'
 * output on the single-file edition's code.
 */
const pick = (o: any, keys: string[]) => Object.fromEntries(keys.map((k) => [k, o[k] === Infinity ? "Infinity" : o[k]]));
const ms = (s: string) => Date.parse(s);

export const SECTIONS: Record<string, (api: any) => any> = {
  format(a) {
    a.setCfg(null);
    return {
      dur: [0, 29999, 30000, 59 * 6e4, 60 * 6e4, 65 * 6e4 + 29e3, 23 * 36e5 + 59 * 6e4, 24 * 36e5, 49 * 36e5 + 5 * 6e4, -90 * 6e4].map(a.dur),
      fmtMin: [0, null, 5, 59.6, 60, 75, 125, 600].map(a.fmtMin),
      parseMin: ["", "  ", "45", "1:30", "1:75", "2h", "1.5h", "1h 15m", "1 hour 5 mins", "90m", "3hrs", "20 minutes", "abc", "1h15", "h", "2:5"].map(a.parseMin).map((v: any) => isNaN(v) ? "NaN" : v),
      rel: ["2026-10-27T11:59:30Z", "2026-10-27T11:15:00Z", "2026-10-27T02:00:00Z", "2026-10-24T12:00:00Z", "2026-10-01T09:30:00Z"].map(a.rel),
      abs: ["2026-03-05T07:08:00Z", "not a date"].map(a.abs),
      initials: ["Jo Bloggs", "tom whitlock (sample)", "Cher", "", "  a  b  c "].map(a.initials),
      slug: ["Acme Ltd!", "---", "Ünïcode name"].map(a.slug),
      median: [[], [3], [5, 1, 4], [4, 1, 3, 2]].map(a.median),
      tone: ["Jo", "Acme Ltd"].map(a.tone),
    };
  },
  normCfg(a) {
    const inputs = [null, "nope", {},
      { tz: "Mars/Olympus", days: [1, 1, 3, 9, "2", 0], start: "09:00", end: "08:00", holidays: ["2026-12-25", "bad", "2026-01-01"], targets: { S1: { hours: "2", always: 1 }, S2: { hours: 0 }, S9: { hours: 5 } } },
      { tz: "America/New_York", start: "07:30", end: "19:00", teams: [" A ", "B", "A", "", null, "x".repeat(70)], categories: [], requireShift: false, name: "  My desk  ", shareUrl: "http://insecure", idPrefix: "ab1", defaults: { severity: "S9", channel: "chat", team: 5 },
        rules: { noteToResolve: 1, maxActive: 12.6, soonHours: 0.1, autoCloseDays: 400, maxShiftHours: "8", graceDays: -1 }, routing: { on: false, cats: { Network: ["u:a", "u:a", "x:b", "l:Eve", 7], Empty: ["bad"] } },
        email: { app: "mailto", templates: { opened: { on: false, subject: "  ", body: "Hi" }, closed: { on: true } } }, announce: { text: "  Outage  ", tone: "loud", until: 5, at: "2026-10-27T10:00:00Z", by: "ana" } },
      { shareUrl: "https://help.example.com/x", idPrefix: "toolong", announce: { text: "   " } },
    ];
    return inputs.map((o) => a.normCfg(o));
  },
  work(a) {
    const out: any = {};
    for (const [cfgName, cfg] of [["default", null], ["ny", NY_CFG]] as [string, any][]) {
      a.setCfg(cfg);
      out[cfgName] = {
        between: WORK_CASES.map(([l, x, y, al]) => [l, a.workBetween(ms(x), ms(y), al)]),
        add: ADD_CASES.map(([l, x, hrs, al]) => [l, a.addWork(ms(x), hrs * 36e5, al)]),
        windows: [[2026, 10, 26], [2026, 10, 31], [2026, 12, 25], [2026, 3, 30], [2026, 11, 26], [2026, 3, 9]].map(([y, m, d]) => a.dayWindow(y, m, d)),
        wall: [a.wallToUtc(2026, 3, 29, 1, 30, a.S.cfg.tz), a.wallToUtc(2026, 7, 1, 9, 0, a.S.cfg.tz), a.tzOffset(ms("2026-07-01T12:00:00Z"), a.S.cfg.tz)],
      };
    }
    a.setCfg(null);
    return out;
  },
  sla(a) {
    const out: any = {};
    for (const [cfgName, cfg] of [["default", null], ["ny", NY_CFG], ["soon8", { rules: { soonHours: 8 } }]] as [string, any][]) {
      a.setCfg(cfg); load(a.S, { customers: CUSTOMERS, tickets: SLA_TICKETS });
      out[cfgName] = a.S.tickets.map((t: any) => [t.id, pick(a.sla(t), ["state", "text", "over", "paused", "key", "due", "el", "T"]), a.target(t)]);
    }
    a.setCfg(null);
    return out;
  },
  async ids(a) {
    a.setCfg(null);
    load(a.S, { customers: CUSTOMERS, tickets: [{ id: "ACME1" }, { id: "ACME3" }, { id: "ACMEX" }, { id: "XACME9" }, { id: "HD-ABCDE" }] });
    const acme = a.S.custById.get("c-acme");
    const r: any = { next: a.nextIdNum(acme), none: a.nextIdNum(null), noPrefix: a.nextIdNum(a.S.custById.get("c-fast")), max: a.maxIdNum("ACME") };
    acme.idStart = 10; r.idStart = a.nextIdNum(acme);
    a.S.counters = { ACME: { next: 15 } }; r.counter = a.nextIdNum(acme);
    acme.idStart = 2; a.S.counters = {};
    r.alloc1 = await a.allocId("c-acme"); r.counters1 = JSON.parse(JSON.stringify(a.S.counters));
    a.S.byId.set("ACME5", { id: "ACME5" });
    a.S.counters = { ACME: { next: 5 } };
    r.alloc2 = await a.allocId("c-acme"); r.counters2 = JSON.parse(JSON.stringify(a.S.counters));
    const g = await a.allocId("c-fast"); r.genShape = /^HD-[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{5}$/.test(g);
    a.setCfg({ idPrefix: "zz9" }); r.genPrefix = (await a.allocId(null)).slice(0, 4);
    a.setCfg(null);
    return r;
  },
  csv(a) {
    return { rows: CSV_CASES.map(a.parseCSV), objects: a.csvObjects("Ticket ID;Title;Colour\nA1;Hello;red\n;World;", a.IMP_COLS.tickets) };
  },
  plans(a) {
    a.setCfg(null);
    load(a.S, { customers: CUSTOMERS, staff: STAFF, names: NAMES, tickets: ROUTE_TICKETS });
    const c = a.csvObjects(CUSTOMER_CSV, a.IMP_COLS.customers), t = a.csvObjects(TICKET_CSV, a.IMP_COLS.tickets);
    const conv = {
      sev: ["S2", "s4 low", "3", "Critical", "urgent", "P2 high", "moderate", "minor", "?", ""].map(a.sevFrom),
      status: ["Closed", "done", "Resolved", "On hold", "Unassigned", "In progress", "nope", ""].map(a.statusFrom),
      tier: ["C", "High", "low", "Normal", "medium", "x"].map(a.tierFrom),
      chan: ["E-mail", "Phone call", "web form", "Teams", "RMM alert", "fax"].map(a.chanFrom),
      date: ["12/01/2026 09:30", "1.2.2026", "2026-02-05 08:00", "2026-02-05T08:00:00Z", "garbage", ""].map(a.dateFrom),
    };
    return { conv, customers: { unknown: c.unknown, plan: a.planCustomers(c.list) }, tickets: { unknown: t.unknown, plan: a.planTickets(t.list) } };
  },
  routing(a) {
    const out: any = {};
    const scen: [string, any][] = [["shift", { routing: { cats: ROUTE_CATS } }], ["limit2", { routing: { cats: ROUTE_CATS }, rules: { maxActive: 2 } }], ["noShift", { routing: { cats: ROUTE_CATS }, requireShift: false }]];
    for (const [name, cfg] of scen) {
      a.setCfg(cfg); a.setDb({}); load(a.S, { staff: STAFF, shifts: SHIFTS, names: NAMES, tickets: ROUTE_TICKETS, customers: CUSTOMERS });
      const pickId = (m: any) => m ? m.id : null;
      out[name] = {
        states: a.S.staff.map((m: any) => [m.id, a.routeState(m)]).concat([["gone", a.routeState(null)]]),
        tickets: a.S.tickets.map((t: any) => [t.id, pickId(a.routePick(t))]),
        cats: Object.keys(ROUTE_CATS).concat(["Software"]).map((c) => [c, pickId(a.routePick({ category: c, history: [] }))]),
        events: a.routeEvents({ category: "Network", status: "new" }, a.S.staff[0], "2026-10-27T12:00:00Z"),
      };
    }
    a.setDb(null); a.setCfg(null);
    return out;
  },
  dispatch(a) {
    a.setCfg(null); load(a.S, { tickets: ROUTE_TICKETS, customers: CUSTOMERS, queues: QUEUES });
    const ids = (l: any[]) => l.map((t) => t.id);
    const un = a.S.tickets.filter((t: any) => ["new", "open", "pending"].includes(t.status) && !t.assigneeId && !t.assigneeLabel);
    return {
      auto: ids(un.slice().sort(a.prio)),
      custom: ids(a.orderCol(un, "none")),
      colNone: ids(a.colTickets("none")), colFay: ids(a.colTickets("u-fay")),
      keys: [a.qKey("a b/c", null), a.qKey(null, "Eve Label"), a.qKey(null, null), a.sanId("x y#z")],
      moves: MOVES.map(([k, id, b, af]) => a.planMove(k, id, b, af)),
    };
  },
  similar(a) {
    load(a.S, { tickets: SIM_TICKETS, customers: CUSTOMERS });
    return {
      toks: [...a.toks("The printers keep jamming and stopped, please help with the jammed printer!")],
      results: SIM_QUERIES.map(([q, o]) => a.similar(q, o).map((x: any) => [x.t.id, Math.round(x.sc * 1e9) / 1e9])),
    };
  },
  hist(a) {
    load(a.S, { customers: CUSTOMERS, names: NAMES });
    const t = JSON.parse(JSON.stringify(HIST_TICKET));
    const closed = { id: "H-2", createdAt: "2026-10-01T00:00:00Z", updatedAt: "2026-10-05T00:00:00Z", resolvedAt: "2026-10-03T00:00:00Z", history: [{ at: "2026-10-03T00:00:00Z", type: "status", to: "closing", by: "ana" }, { at: "2026-10-04T00:00:00Z", type: "status", to: "closed", auto: true, byLabel: "x" }] };
    return { hits: HIST_QUERIES.map((q) => a.histHit(t, q)), close: [a.closeInfo(closed), a.closeInfo({ id: "H-3", updatedAt: "2026-10-09T00:00:00Z", history: [] })], keys: [a.histKey(t), a.histKey({ assigneeLabel: "Eve" }), a.histKey({})] };
  },
  pins(a) {
    load(a.S, { pins: PINS }); a.setCfg(null);
    const ids = (w: string) => a.pinsFor(w).map((p: any) => [p.id, p.expired]);
    a.setDb({}); a.S.isEditor = true; const mgr = { queue: ids("queue"), dispatch: ids("dispatch") };
    a.S.isEditor = false; const agent = { queue: ids("queue"), dispatch: ids("dispatch") };
    a.setDb(null);
    return { mgr, agent };
  },
  text(a) {
    load(a.S, { names: NAMES });
    const ev = [
      { type: "created" }, { type: "status", from: "open", to: "closing", auto: true, reason: "The grace period ended" }, { type: "email", action: "sent", to: "jo@x", subject: "Hi" }, { type: "email", action: "skipped" },
      { type: "severity", from: "S3", to: "S1" }, { type: "team", from: "A", to: "B" }, { type: "channel", from: null, to: "chat" }, { type: "assignee", from: "ana", toLabel: "Eve", auto: true, reason: "Network auto-assign order" },
      { type: "assignee", fromLabel: "Eve" }, { type: "note", internal: true, minutes: 75, billable: false }, { type: "note", timeOnly: true, minutes: 30, billable: true }, { type: "timeline", started: true }, { type: "timeline", phase: "Analysis" }, { type: "weird" },
    ];
    const wev = [
      { type: "customer", action: "contact-added", detail: "Jo" }, { type: "customer", action: "created" }, { type: "staff", action: "updated", target: "ana", detail: "teams A" }, { type: "staff", action: "joined", targetLabel: "Eve", detail: "Security" },
      { type: "staff", action: "avail", target: "zz", from: "available", to: "leave" }, { type: "staff", action: "oncall", to: true }, { type: "shift", action: "out", target: "ana", auto: true, minutes: 125 }, { type: "shift", action: "in" },
      { type: "queue", action: "reset", target: "ana" }, { type: "queue", action: "reordered", detail: "R1 to position 2" }, { type: "request", action: "created", target: "ben", detail: "asks to take R1" }, { type: "request", action: "declined", detail: "x" },
      { type: "settings" }, { type: "pin", action: "removed", detail: "Old" }, { type: "share" }, { type: "other" },
    ];
    return { ev: ev.map((e) => a.evText(e)), wev: wev.map((e) => a.eventText(e)) };
  },
};
